<?php
declare(strict_types=1);
require_once __DIR__.'/harness.php';require_once __DIR__.'/database.php';require_once __DIR__.'/support-b-fixture.php';
use Hostider\Core\{Id,CanonicalJson};
use Hostider\Core\Http\HttpError;
use Hostider\Support\Work\{Time,Commands};
function paFixture(bool $policy=true): array{
    $f=supportFixture();supportGrant($f,$f['departments'][0]);$a=$f['db']->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL',[$f['admin']['user']])->fetchColumn();$f['db']->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope,department_scope) VALUES (?,?,?,?,?)',[Id::uuid(),$a,'support.ticket.assign',$f['client']['customer'],$f['departments'][0]]);$f['engine']=new \Hostider\Support\Work\Engine($f['c']);if($policy){bPublish($f,bPolicy());}return $f;
}
function paCycle(array $f,string $id): array{
    $db=$f['db'];return ['cycle'=>$db->execute('SELECT * FROM support_sla_cycles WHERE id=?',[$id])->fetch(),'clocks'=>$db->execute('SELECT * FROM support_sla_clocks WHERE cycle_id=? ORDER BY id',[$id])->fetchAll(),'history'=>$db->execute('SELECT h.* FROM support_sla_history h JOIN support_sla_clocks c ON c.id=h.clock_id WHERE c.cycle_id=? ORDER BY h.id',[$id])->fetchAll()];
}
function paFirst(array $f,array $t): array{return array_values(array_filter(bClocks($f,$t),fn($r)=>$r['metric']==='FIRST'))[0];}
function paCounts(array $f): array{$out=[];foreach(['support_tickets','support_messages','support_events','support_work_tickets','support_sla_cycles','support_sla_clocks','support_sla_history','support_work_events','outbox_events','idempotency_keys'] as $table){$out[$table]=(int)$f['db']->execute('SELECT COUNT(*) FROM '.$table)->fetchColumn();}return $out;}
function paClient(HttpTestServer $s,array $who,array &$auth): void{bHttp($s,'/api/v1/client/identity/bootstrap',$auth);same(200,bHttp($s,'/api/v1/client/identity/login',$auth,['email'=>$who['email'],'password'=>$who['password']])[0]);}
function paCreate(array $f): array{return ['department_id'=>$f['departments'][0],'subject'=>'Synthetic P1 request','body'=>'Synthetic request body','priority'=>'NORMAL'];}
function paClosedCalendar(string $start): array{
    $p=bPolicy();$d=new DateTimeImmutable($start,new DateTimeZone('UTC'));for($n=0;$n<3660;++$n){$p['calendar']['exceptions'][$d->format('Y-m-d')]=[];$d=$d->modify('+1 day');}return $p;
}
test('F5-B P1 resolved staff reopen completes exactly one new FIRST and preserves old cycle',function(): void{
    $f=paFixture();$t=bTicket($f);bState($f,$t,'RESOLVED');$old=bWork($f,$t)['cycle_id'];$snapshot=paCycle($f,$old);$p=bPolicy();$p['targets']['NORMAL']['FIRST']=7;$policy=bPublish($f,$p);$r=bReply($f,$t);$w=bWork($f,$t);same(false,$old===$w['cycle_id']);same($policy['id'],$w['policy_id']);$first=paFirst($f,$t);same('COMPLETED',$first['status']);same(0,(int)$first['consumed_us']);same(7*Time::MINUTE,(int)$first['target_us']);same($first['last_at'],$first['completed_at']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_sla_history WHERE clock_id=? AND kind='COMPLETED'",[$first['id']])->fetchColumn());same($snapshot,paCycle($f,$old));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_sla_alerts')->fetchColumn());same($r['message_id'],$f['db']->execute('SELECT subject_id FROM support_events WHERE id=?',[$first['source_event']])->fetchColumn());
});
test('F5-B P1 permitted CLOSED staff reopen completes FIRST and replay is an exact no-op',function(): void{
    $f=paFixture();bHold($f);$t=bTicket($f);bState($f,$t,'CLOSED');$old=bWork($f,$t)['cycle_id'];$snapshot=paCycle($f,$old);$body=['id'=>$t['id'],'version'=>(int)bRow($f,$t)['version'],'body'=>'Synthetic reopen'];$key=Id::uuid();$r=$f['service']->command($f['admin']['reference'],'admin','reply',$body,$key,Id::uuid());$before=bSnapshot($f);same($r,$f['service']->command($f['admin']['reference'],'admin','reply',$body,$key,Id::uuid()));same($before,bSnapshot($f));same('COMPLETED',paFirst($f,$t)['status']);same($snapshot,paCycle($f,$old));same(409,raises(HttpError::class,fn()=>$f['service']->command($f['admin']['reference'],'admin','reply',$body,Id::uuid(),Id::uuid()))->status);
});
test('F5-B P1 customer reopen leaves FIRST pending until a genuine staff reply',function(): void{
    $f=paFixture();$t=bTicket($f);bReply($f,$t);bState($f,$t,'RESOLVED');$old=bWork($f,$t)['cycle_id'];$snapshot=paCycle($f,$old);bReply($f,$t,client:true);same('RUNNING',paFirst($f,$t)['status']);same(0,count(array_filter(bClocks($f,$t),fn($r)=>$r['metric']==='NEXT')));bReply($f,$t,'note');same('RUNNING',paFirst($f,$t)['status']);bReply($f,$t);same('COMPLETED',paFirst($f,$t)['status']);same($snapshot,paCycle($f,$old));
});
test('F5-B P1 parallel native HTTP reopen replies create one cycle completion and public outbox',function(): void{
    $f=paFixture();$t=bTicket($f);bState($f,$t,'RESOLVED');$old=bWork($f,$t)['cycle_id'];$snapshot=paCycle($f,$old);$servers=[new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php'),new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php')];$auth=['cookies'=>[],'csrf'=>''];$children=[];
    try{bLogin($servers[0],$f['admin'],$auth);$cookie=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($auth['cookies']),$auth['cookies']));$before=(int)$f['db']->execute("SELECT COUNT(*) FROM outbox_events WHERE event_type='support.changed'")->fetchColumn();$version=(int)bRow($f,$t)['version'];foreach($servers as $server){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/support-http-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($p)){throw new RuntimeException('Child unavailable');}fwrite($pipes[0],json_encode(['url'=>'http://127.0.0.1:'.$server->diagnostics()['port'].'/api/v1/admin/support/reply','body'=>['id'=>$t['id'],'version'=>$version,'body'=>'Synthetic parallel reopen'],'key'=>Id::uuid(),'cookie'=>$cookie,'csrf'=>$auth['csrf']],JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$p,$pipes];}$status=[];foreach($children as [$p,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($p));same('',$err);$status[]=json_decode($raw,true,32,JSON_THROW_ON_ERROR)['status'];}sort($status);same([200,409],$status);same(2,(int)$f['db']->execute('SELECT COUNT(*) FROM support_sla_cycles WHERE ticket_id=?',[$t['id']])->fetchColumn());$first=paFirst($f,$t);same('COMPLETED',$first['status']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_sla_history WHERE clock_id=? AND kind='COMPLETED'",[$first['id']])->fetchColumn());same($before+1,(int)$f['db']->execute("SELECT COUNT(*) FROM outbox_events WHERE event_type='support.changed'")->fetchColumn());same($snapshot,paCycle($f,$old));}finally{foreach($servers as $s){$s->stop();}}
});
test('F5-B P1 HTTP empty weekly policy is rejected without writes and client can still create',function(): void{
    $f=paFixture(false);$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];$client=$a;try{bLogin($server,$f['admin'],$a);$p=bPolicy();$p['calendar']['weekly']=array_fill(1,7,[]);$before=paCounts($f);$r=bHttp($server,'/api/v1/admin/support-work/prepare',$a,['action'=>'policy-publish','payload'=>['department_id'=>$f['departments'][0],'version'=>0,'policy'=>$p]]);same(422,$r[0]);same(true,str_contains($r[2],'SLA_POLICY_UNSCHEDULABLE'));same($before,paCounts($f));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_work_policies')->fetchColumn());paClient($server,$f['client'],$client);$r=bHttp($server,'/api/v1/client/support/create',$client,paCreate($f));same(200,$r[0]);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_tickets')->fetchColumn());same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());}finally{$server->stop();}
});
test('F5-B P1 HTTP exception horizon policy is rejected and previous policy stays usable',function(): void{
    $f=paFixture();$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];try{bLogin($server,$f['admin'],$a);$p=paClosedCalendar(substr(Time::format(Time::now($f['db'])),0,10));$before=paCounts($f);$r=bHttp($server,'/api/v1/admin/support-work/prepare',$a,['action'=>'policy-publish','payload'=>['department_id'=>$f['departments'][0],'version'=>1,'policy'=>$p]]);same(422,$r[0]);same(true,str_contains($r[2],'SLA_POLICY_UNSCHEDULABLE'));same($before,paCounts($f));$t=bTicket($f);same(2,count(bClocks($f,$t)));}finally{$server->stop();}
});
test('F5-B P1 future calendar failure preserves HTTP ticket message and explicit idempotent unavailable result',function(): void{
    $f=paFixture();$future=Time::date(Time::now($f['db']))->modify('+30 days')->format('Y-m-d');$p=paClosedCalendar($future);$policy=bPublish($f,$p);$immutable=$f['db']->execute('SELECT * FROM support_work_policies WHERE id=?',[$policy['id']])->fetch();$f['db']->execute("CREATE TRIGGER p1_future_event BEFORE INSERT ON support_events FOR EACH ROW BEGIN IF NEW.kind='CREATED' THEN SET NEW.created_at='$future 12:00:00'; END IF; END");$s=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];$admin=$a;try{paClient($s,$f['client'],$a);$key=Id::uuid();$r=bHttp($s,'/api/v1/client/support/create',$a,paCreate($f),$key);same(200,$r[0]);same('UNAVAILABLE',$r[1]['data']['sla_status']);same('SLA_CALENDAR_UNAVAILABLE',$r[1]['data']['warning']);$t=$r[1]['data'];$before=paCounts($f);same($r[1]['data'],bHttp($s,'/api/v1/client/support/create',$a,paCreate($f),$key)[1]['data']);same($before,paCounts($f));same(1,$before['support_tickets']);same(1,$before['support_messages']);same(1,$before['support_events']);same(0,$before['support_sla_cycles']);same(0,$before['support_sla_clocks']);same(0,$before['support_sla_history']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='SLA_UNAVAILABLE'")->fetchColumn());$f['engine']->tick($t['id']);$f['engine']->tick($t['id']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='SLA_UNAVAILABLE'")->fetchColumn());bLogin($s,$f['admin'],$admin);$v=bHttp($s,'/api/v1/admin/support-work/detail?id='.$t['id'],$admin);same(200,$v[0]);same('UNAVAILABLE',$v[1]['data']['sla_status']);same([],$v[1]['data']['clocks']);same($immutable,$f['db']->execute('SELECT * FROM support_work_policies WHERE id=?',[$policy['id']])->fetch());}finally{$s->stop();$f['db']->execute('DROP TRIGGER p1_future_event');}
});
test('F5-B P1 valid HTTP create is atomic and SQL failure leaves no partial support or idempotency rows',function(): void{
    $f=paFixture();$s=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];try{paClient($s,$f['client'],$a);$r=bHttp($s,'/api/v1/client/support/create',$a,paCreate($f));same(200,$r[0]);$t=$r[1]['data'];same(['FIRST','RESOLUTION'],array_column(bClocks($f,$t),'metric'));same(1,paCounts($f)['support_tickets']);$before=paCounts($f);$f['db']->execute("CREATE TRIGGER p1_history_failure BEFORE INSERT ON support_sla_history FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic P1 rollback'");$key=Id::uuid();try{same(500,bHttp($s,'/api/v1/client/support/create',$a,paCreate($f),$key)[0]);same($before,paCounts($f));}finally{$f['db']->execute('DROP TRIGGER p1_history_failure');}same(200,bHttp($s,'/api/v1/client/support/create',$a,paCreate($f),$key)[0]);same(2,paCounts($f)['support_tickets']);}finally{$s->stop();}
});
test('F5-B P1 active-cycle horizon failure preserves snapshots replies and cross-department recovery',function(): void{
    $f=paFixture();$t=bTicket($f);$cycle=bWork($f,$t)['cycle_id'];$snapshot=paCycle($f,$cycle);$future=Time::now($f['db'])+3662*86400*1_000_000;same(true,$f['engine']->tick($t['id'],$future));same($snapshot,paCycle($f,$cycle));same('UNAVAILABLE',bWork($f,$t)['sla_status']);$r=bReply($f,$t);same('SLA_CALENDAR_UNAVAILABLE',$r['warning']);same($snapshot,paCycle($f,$cycle));$f['engine']->tick($t['id'],$future);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='SLA_UNAVAILABLE'")->fetchColumn());$dep=$f['departments'][1];supportGrant($f,$dep);bPublish($f,bPolicy(),$dep);$f['service']->command($f['admin']['reference'],'admin','move',['id'=>$t['id'],'version'=>(int)bRow($f,$t)['version'],'department_id'=>$dep],Id::uuid(),Id::uuid());$w=bWork($f,$t);same('ACTIVE',$w['sla_status']);same($dep,$w['department_id']);same(null,$w['assignee_id']);same(false,$cycle===$w['cycle_id']);same($snapshot,paCycle($f,$cycle));same($f['client']['customer'],bRow($f,$t)['customer_id']);
});
test('F5-B P1 additive 050 to 051 preserves all prior checksums and replays without work',function(): void{
    $root=dirname(__DIR__);$db=isolatedDomainDb();$dir=$root.'/storage/f5-b-audit-prefix-'.bin2hex(random_bytes(5));mkdir($dir,0700);$files=[];try{foreach(glob($root.'/migrations/*.php') as $p){if(basename($p)<'051'){$to=$dir.'/'.basename($p);copy($p,$to);$files[]=$to;}}same(50,count((new \Hostider\Core\Database\Migrator($db,$dir))->migrate()));$before=$db->execute('SELECT version,checksum,status FROM schema_migrations ORDER BY version')->fetchAll();$m=new \Hostider\Core\Database\Migrator($db,$root.'/migrations');same(['051_support_sla_availability.php','052_support_mail.php','053_support_automation_incident_csat.php','054_support_ui_state.php','055_support_auto_close.php'],$m->migrate());same([],$m->migrate());$m->assertReady();same($before,$db->execute("SELECT version,checksum,status FROM schema_migrations WHERE version<'051' ORDER BY version")->fetchAll());same(1,(int)$db->execute("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='support_work_tickets' AND column_name='sla_status'")->fetchColumn());}finally{foreach($files as $p){unlink($p);}rmdir($dir);}
});
test('F5-B P1 failed target calendar move rolls back SLA side effects and records correct policy',function(): void{
    $f=paFixture();bRoster($f,$f['admin']['user']);$t=bTicket($f);bCommand($f,'assign',['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['admin']['user']]);$cycle=bWork($f,$t)['cycle_id'];$snapshot=paCycle($f,$cycle);$dep=$f['departments'][1];supportGrant($f,$dep);$future=Time::date(Time::now($f['db']))->modify('+30 days')->format('Y-m-d');$policy=bPublish($f,paClosedCalendar($future),$dep);$f['db']->execute("CREATE TRIGGER p1_move_future BEFORE INSERT ON support_events FOR EACH ROW BEGIN IF NEW.kind='MOVE' THEN SET NEW.created_at='$future 12:00:00'; END IF; END");try{$r=$f['service']->command($f['admin']['reference'],'admin','move',['id'=>$t['id'],'version'=>(int)bRow($f,$t)['version'],'department_id'=>$dep],Id::uuid(),Id::uuid());same('SLA_CALENDAR_UNAVAILABLE',$r['warning']);$w=bWork($f,$t);same($dep,$w['department_id']);same(null,$w['assignee_id']);same(null,$w['cycle_id']);same('UNAVAILABLE',$w['sla_status']);same($snapshot,paCycle($f,$cycle));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_sla_alerts')->fetchColumn());$details=json_decode($f['db']->execute("SELECT details FROM support_work_events WHERE kind='SLA_UNAVAILABLE'")->fetchColumn(),true,32,JSON_THROW_ON_ERROR);same($policy['id'],$details['attempted_policy_id']);same($cycle,$details['retained_cycle_id']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='UNASSIGNED'")->fetchColumn());same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages WHERE ticket_id=?',[$t['id']])->fetchColumn());same($f['client']['customer'],bRow($f,$t)['customer_id']);}finally{$f['db']->execute('DROP TRIGGER p1_move_future');}
});
